from pathlib import Path
p = Path('src/dump.c')
text = p.read_text().splitlines(True)
# Insert <stdint.h> after existing includes if not present
if not any('#include <stdint.h>' in l for l in text[:50]):
    for i,l in enumerate(text):
        if l.startswith('#include <string.h>'):
            text.insert(i+1, '#include <stdint.h>\n')
            break
    else:
        # fallback: after last include
        for i,l in enumerate(text):
            if l.startswith('#include'):
                last=i
        text.insert(last+1, '#include <stdint.h>\n')
    p.write_text(''.join(text))
    print('inserted stdint.h into src/dump.c')
else:
    print('stdint.h already present')
