    # insert after string.h include if present else after mruby.h
    if '#include <string.h>' in text:
        text = text.replace('#include <string.h>\n', '#include <string.h>\n#include <stdint.h>\n')
    else:
        text = text.replace('#include <mruby.h>\n', '#include <mruby.h>\n#include <stdint.h>\n')

# Replace symhash implementation to avoid UB on 32-bit unsigned shifts
pat = re.compile(r"static uint8_t\n(symhash\(const char \*key, size_t len\)\n\{)\n(.*?)\n\}\n", re.S)
m = pat.search(text)
if not m:
    raise SystemExit('symhash function not found')
new_body = """static uint8_t
symhash(const char *key, size_t len)
{
    uint64_t hash, i;

    for (hash = i = 0; i < len; ++i) {
        hash += (uint8_t)key[i];
        hash += (hash << 10);
        hash ^= (hash >> 6);
    }
    hash += (hash << 3);
    hash ^= (hash >> 11);
    hash += (hash << 15);
    return (uint8_t)(hash & 0xff);
}
"""
